INSERT INTO [dbo].[OWPLeague] (OWPLeagueName, CategoryId, IsActive, IsBlackList, New_CategoryId)
SELECT 
	LeagueName,NULL,1,NULL,NULL
FROM #NewLeague
WHERE NOT EXISTS (
        SELECT 1 
        FROM [dbo].[OWPLeague]
        WHERE [OWPLeagueName] = LeagueName
    )


