SELECT l.[OWPLeagueId]
INTO #UpdateEndDate
FROM #TempTable as temp
LEFT JOIN #LeagueGroup as lg 
    ON lg.LeagueName = temp.newlg
LEFT JOIN [dbo].[OWPLeague] as l 
    ON l.[OWPLeagueName] = temp.League
LEFT JOIN [dbo].[RefResource] as lc 
    ON lc.[RefName] = 'LeagueCategory'
    AND lc.[Value] = lg.Value
WHERE temp.League IS NOT NULL 
	AND temp.League <> ''
	AND l.[OWPLeagueId] is not null
	AND NOT EXISTS (
        SELECT 1 
        FROM [dbo].[LeagueCategoryHistory] AS lch
        WHERE lch.[OWPLeagueId] = l.[OWPLeagueId] 
          AND lch.[EndDate] IS NULL
          AND lch.[CategoryId] = lc.[ResourceId]
    )
	AND EXISTS (
        SELECT 1 
        FROM [dbo].[LeagueCategoryHistory] AS lch
        WHERE lch.[OWPLeagueId] = l.[OWPLeagueId] 
          AND lch.[EndDate] IS NULL
    )

UPDATE lch
SET lch.[EndDate] = '2024-12-31'
FROM [dbo].[LeagueCategoryHistory] lch
INNER JOIN #UpdateEndDate u ON lch.[OWPLeagueId] = u.[OWPLeagueId]
WHERE lch.[EndDate] IS NULL


INSERT INTO [dbo].[LeagueCategoryHistory] ([OWPLeagueId], [CategoryId], [StartDate], [EndDate])
SELECT 
    l.[OWPLeagueId],
    lc.[ResourceId],
    '2025-01-01',
    NULL
FROM #TempTable as temp
LEFT JOIN #LeagueGroup as lg 
    ON lg.LeagueName = temp.newlg
LEFT JOIN [dbo].[OWPLeague] as l 
    ON l.[OWPLeagueName] = temp.League
LEFT JOIN [dbo].[RefResource] as lc 
    ON lc.[RefName] = 'LeagueCategory'
    AND lc.[Value] = lg.Value
WHERE temp.League IS NOT NULL 
	AND temp.League <> ''
	AND l.[OWPLeagueId] is not null
	AND NOT EXISTS (
        SELECT 1 
        FROM [dbo].[LeagueCategoryHistory] AS lch
        WHERE lch.[OWPLeagueId] = l.[OWPLeagueId] 
          AND lch.[EndDate] IS NULL
          AND lch.[CategoryId] = lc.[ResourceId]
    )

DROP TABLE #UpdateEndDate;
DROP TABLE #TempTable;
DROP TABLE #LeagueGroup;
DROP TABLE #NewLeague;



